const TEXT_W = 9360; // 6.5 in
const body = (text, opts = {}) => new Paragraph({ spacing: { line: 480, after: 0 }, alignment: AlignmentType.LEFT, children: runs(text), ...opts });
const single = (text, opts = {}) => new Paragraph({ spacing: { line: 276, after: 120 }, children: runs(text), ...opts });
function runs(text) { // **bold** and *italic* markup
  const out = []; const re = /(\*\*[^*]+\*\*|\*[^*]+\*)/g; let last = 0; let m;
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(new TextRun(text.slice(last, m.index)));
    const t = m[0]; out.push(t.startsWith("**") ? new TextRun({ text: t.slice(2, -2), bold: true }) : new TextRun({ text: t.slice(1, -1), italics: true }));
    last = m.index + t.length;
  }
  if (last < text.length) out.push(new TextRun(text.slice(last)));
  return out;
}
function runsSized(text, size, boldAll) { // markup-aware runs with explicit size
  const out = []; const re = /(\*\*[^*]+\*\*|\*[^*]+\*)/g; let last = 0; let m;
  while ((m = re.exec(text))) {
    if (m.index > last) out.push(new TextRun({ text: text.slice(last, m.index), size, bold: boldAll }));
    const t = m[0]; out.push(t.startsWith("**") ? new TextRun({ text: t.slice(2, -2), bold: true, size }) : new TextRun({ text: t.slice(1, -1), italics: true, size, bold: boldAll }));
    last = m.index + t.length;
  }
  if (last < text.length) out.push(new TextRun({ text: text.slice(last), size, bold: boldAll }));
  return out;
}
