function buildChapter2() {
  const out = []; let first = true;
  for (const b of ch2) {
    if (b.t === "h1") { out.push(first ? h1("Chapter 2—Literature Review") : h1(b.x)); first = false; }
    else if (b.t === "h2") out.push(h2(b.x));
    else if (b.t === "h3") out.push(h3(b.x));
    else if (b.t === "p") out.push(body(b.x));
    else if (b.t === "bullets") out.push(...bullets(b.items));
    else if (b.t === "caption") { if (b.kind === "Figure") out.push(figure(FIG.fig21)); out.push(caption(b.kind, `${b.kind} ${b.num}. ${b.x}`)); }
    else if (b.t === "table") { const n = b.rows[0].length; out.push(table(b.rows, n === 3 ? [2200, 3800, 3360] : n === 4 ? [2000, 2600, 2400, 2360] : undefined, { size: 17 })); out.push(new Paragraph({ spacing: { after: 120 } })); }
  }
  return out;
}

